const AdmZip = require('adm-zip');
const zip = new AdmZip('/workspace/testbed/docs/travel_summary.docx');
const entry = zip.getEntry('word/document.xml');
let xml = entry.getData().toString('utf8');

// The note to append
const note = 'Note: Maya Chen has a total of 5 Seattle-related travel records, including 1 flight, 1 hotel reservation (cancelled), and 3 car rentals (2 confirmed, 1 cancelled).';

// Insert a new paragraph just before the closing </w:body> tag
const newParagraph = '<w:p><w:r><w:t>' + note + '</w:t></w:r></w:p>';
xml = xml.replace('</w:body>', newParagraph + '</w:body>');

zip.updateFile('word/document.xml', Buffer.from(xml, 'utf8'));
zip.writeZip('/workspace/testbed/docs/travel_summary.docx');
console.log('Done!');
"

