const mammoth = require('mammoth');
const PDFDocument = require('pdfkit');
const fs = require('fs');

mammoth.extractRawText({path: '/workspace/testbed/docs/travel_summary.docx'})
  .then(result => {
    const text = result.value;
    const doc = new PDFDocument({size: 'A4', margin: 50});
    const stream = fs.createWriteStream('/workspace/testbed/docs/travel_summary.pdf');
    doc.pipe(stream);

    const lines = text.split('\n');
    for (const line of lines) {
      if (line.trim() === '') {
        doc.moveDown(0.5);
      } else if (['Travel Booking Summary', 'Flights', 'Hotels', 'Car Rentals'].includes(line.trim())) {
        doc.fontSize(14).font('Helvetica-Bold').text(line.trim());
        doc.moveDown(0.3);
      } else if (line.startsWith('Note:')) {
        doc.moveDown(0.5);
        doc.fontSize(10).font('Helvetica-Oblique').text(line.trim());
      } else {
        doc.fontSize(9).font('Helvetica').text(line.trim());
      }
    }

    doc.end();
    stream.on('finish', () => console.log('Done!'));
  })
  .catch(err => console.error('Error:', err));
"
